// Agoda — chemical formula: count atoms (LeetCode 726), then weight, then validation.
// Grammar: formula := part*;  part := ELEMENT count? | '(' formula ')' count?;  ELEMENT := [A-Z][a-z]*;  count := [1-9][0-9]*
public static class Formula {
    // Canonical count string: elements in alphabetical (ordinal) order, count omitted when 1. "Mg(OH)2" -> "H2MgO2".
    public static string CountAtoms(string formula) {
        var counts = Parse(formula);
        var sb = new System.Text.StringBuilder();
        foreach (var (el, n) in counts) { sb.Append(el); if (n > 1) sb.Append(n); }
        return sb.ToString();
    }

    // Molecular weight from an element -> mass table. Unknown element -> ArgumentException.
    public static double Weight(string formula, IReadOnlyDictionary<string, double> masses) {
        if (masses == null) throw new ArgumentNullException(nameof(masses));
        double w = 0;
        foreach (var (el, n) in Parse(formula)) {
            if (!masses.TryGetValue(el, out var m)) throw new ArgumentException("unknown element: " + el);
            w += m * n;
        }
        return w;
    }

    // Iterative parse with a stack of count maps, so deep nesting cannot overflow the call stack.
    static SortedDictionary<string, long> Parse(string f) {
        var result = new SortedDictionary<string, long>(StringComparer.Ordinal);
        if (string.IsNullOrEmpty(f)) return result;
        var stack = new Stack<Dictionary<string, long>>();
        stack.Push(new Dictionary<string, long>());
        int i = 0;
        while (i < f.Length) {
            char c = f[i];
            if (c == '(') { stack.Push(new Dictionary<string, long>()); i++; }
            else if (c == ')') {
                if (stack.Count == 1) throw new FormatException("unmatched ')' at " + i);
                i++;
                long mult = ReadCount(f, ref i);
                var inner = stack.Pop();
                if (inner.Count == 0) throw new FormatException("empty group before " + i);
                var top = stack.Peek();
                foreach (var (el, n) in inner) top[el] = checked(top.GetValueOrDefault(el) + n * mult);
            }
            else if (c >= 'A' && c <= 'Z') {
                int start = i++;
                while (i < f.Length && f[i] >= 'a' && f[i] <= 'z') i++;
                string el = f.Substring(start, i - start);
                long n = ReadCount(f, ref i);
                var top = stack.Peek();
                top[el] = checked(top.GetValueOrDefault(el) + n);
            }
            else throw new FormatException($"unexpected '{c}' at {i}");
        }
        if (stack.Count != 1) throw new FormatException("unmatched '('");
        foreach (var (el, n) in stack.Pop()) result[el] = n;
        return result;
    }

    static long ReadCount(string f, ref int i) {
        if (i >= f.Length || !char.IsAsciiDigit(f[i])) return 1;
        if (f[i] == '0') throw new FormatException("count cannot start with 0 at " + i);
        long n = 0;
        while (i < f.Length && char.IsAsciiDigit(f[i])) n = checked(n * 10 + (f[i++] - '0'));
        return n;
    }
}
